namespace VisualRelay.Core.Costs;

/// <summary>
/// A daily recurring time window that multiplies all rate components when the
/// evaluation instant falls inside it.
///
/// The window matches <c>[StartLocal, EndLocal)</c> — start inclusive, end
/// exclusive — in the local time of <see cref="TimeZoneId"/>. The timezone ID
/// must resolve via <see cref="TimeZoneInfo.FindSystemTimeZoneById"/> (IANA or
/// Windows). When no window matches, the base rates apply unmodified.
/// </summary>
internal sealed record RateWindow(
    TimeOnly StartLocal,
    TimeOnly EndLocal,
    string TimeZoneId,
    double Multiplier);

