    // Resolve the evaluation instant for schedule-aware pricing.
    // When not supplied explicitly, read the report's top-level "timestamp"
    // (the stage-end instant). Individual llm_call entries carry no timestamps,
    // and stages are bounded by the stage ceiling, so at most one rate-window
    // boundary crossing can occur per stage — this approximation is acceptable.
    var instant = evaluationInstant ?? ReadTimestamp(report);

    if (!RelayPricing.Default.TryGetValue(model, out var pricing))
    {
        return new RelayCostEstimate(model, 0, false, uncachedTokens, cachedTokens, outputTokens, duration, cacheWriteTokens, llmCalls.Length);
    }

    var multiplier = GetScheduleMultiplier(pricing, instant);
    var cachedRate = pricing.CachedInput ?? pricing.Input;
    var cacheWriteRate = pricing.CacheWrite ?? pricing.Input;
    var usd = (
        uncachedTokens * pricing.Input +
        cachedTokens * cachedRate +
        cacheWriteTokens * cacheWriteRate +
        outputTokens * pricing.Output
    ) * multiplier / 1_000_000d;
    return new RelayCostEstimate(model, usd, true, uncachedTokens, cachedTokens, outputTokens, duration, cacheWriteTokens, llmCalls.Length);
}

private static double GetScheduleMultiplier(ModelPricing pricing, DateTime utcInstant)
{
    // Placeholder — always returns 1.0. Schedule math will be implemented next.
    return 1.0;
}

private static DateTime ReadTimestamp(JsonElement report)
{
    if (report.TryGetProperty("timestamp", out var tsProp) &&
        tsProp.ValueKind == JsonValueKind.String &&
        DateTime.TryParse(tsProp.GetString(), null, System.Globalization.DateTimeStyles.AdjustToUniversal, out var parsed))
    {
        return parsed;
    }
    return DateTime.MinValue;
}

