using System.Globalization;
using System.Text.Json;
using VisualRelay.Core.Costs;

namespace VisualRelay.Tests;

public sealed class RelayPricingScheduleTests
{
    // ── Schedule math: cheap (DeepSeek) model ────────────────────

    [Fact]
    public void CheapModel_InsidePeakWindow_DoublesAllRates()
    {
        // 2026-07-15T01:00:00Z = 09:00 Asia/Shanghai — first peak window start (inclusive).
        // uncached=1500, cached=100, output=ceil(12/4)+2*50=103.
        // base cost = 0.00023912; peak = 2× = 0.00047824.
        using var document = JsonDocument.Parse(
            """
            {
              "model": "cheap",
              "timestamp": "2026-07-15T01:00:00Z",
              "result": { "answer": "abcdefghijkl" },
              "stats": {
                "total_llm_time_s": 1.5,
                "total_tool_time_s": 0.25,
                "prompt_cache": { "cached_tokens": 100 }
              },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 1000 },
                { "type": "tool_call", "prompt_tokens_est": 9999 },
                { "type": "llm_call", "prompt_tokens_est": 1500 }
              ]
            }
            """);

        var cost = RelayCostEstimator.EstimateReport(document.RootElement);

        Assert.True(cost.Priced);
        Assert.Equal("cheap", cost.Model);
        Assert.Equal(0.00047824, cost.CostUsd, precision: 10);
    }

    [Fact]
    public void CheapModel_OffPeak_UsesBaseRates()
    {
        // 2026-07-15T00:00:00Z = 08:00 Asia/Shanghai — before first peak window.
        using var document = JsonDocument.Parse(
            """
            {
              "model": "cheap",
              "timestamp": "2026-07-15T00:00:00Z",
              "result": { "answer": "abcdefghijkl" },
              "stats": {
                "total_llm_time_s": 1.5,
                "total_tool_time_s": 0.25,
                "prompt_cache": { "cached_tokens": 100 }
              },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 1000 },
                { "type": "tool_call", "prompt_tokens_est": 9999 },
                { "type": "llm_call", "prompt_tokens_est": 1500 }
              ]
            }
            """);

        var cost = RelayCostEstimator.EstimateReport(document.RootElement);

        Assert.True(cost.Priced);
        Assert.Equal(0.00023912, cost.CostUsd, precision: 10);
    }

    [Fact]
    public void CheapModel_BetweenPeakWindows_UsesBaseRates()
    {
        // 2026-07-15T04:01:00Z = 12:01 Asia/Shanghai — between the two peak windows.
        using var document = JsonDocument.Parse(
            """
            {
              "model": "cheap",
              "timestamp": "2026-07-15T04:01:00Z",
              "result": { "answer": "abcdefghijkl" },
              "stats": {
                "total_llm_time_s": 1.5,
                "total_tool_time_s": 0.25,
                "prompt_cache": { "cached_tokens": 100 }
              },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 1000 },
                { "type": "tool_call", "prompt_tokens_est": 9999 },
                { "type": "llm_call", "prompt_tokens_est": 1500 }
              ]
            }
            """);

        var cost = RelayCostEstimator.EstimateReport(document.RootElement);

        Assert.True(cost.Priced);
        Assert.Equal(0.00023912, cost.CostUsd, precision: 10);
    }

    [Fact]
    public void CheapModel_EndBoundaryIsExclusive()
    {
        // 2026-07-15T04:00:00Z = 12:00 Asia/Shanghai — EndLocal of first window (exclusive).
        using var document = JsonDocument.Parse(
            """
            {
              "model": "cheap",
              "timestamp": "2026-07-15T04:00:00Z",
              "result": { "answer": "abcdefghijkl" },
              "stats": {
                "total_llm_time_s": 1.5,
                "total_tool_time_s": 0.25,
                "prompt_cache": { "cached_tokens": 100 }
              },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 1000 },
                { "type": "tool_call", "prompt_tokens_est": 9999 },
                { "type": "llm_call", "prompt_tokens_est": 1500 }
              ]
            }
            """);

        var cost = RelayCostEstimator.EstimateReport(document.RootElement);

        Assert.True(cost.Priced);
        Assert.Equal(0.00023912, cost.CostUsd, precision: 10);
    }

    [Fact]
    public void CheapModel_SecondWindowEndBoundaryIsExclusive()
    {
        // 2026-07-15T10:00:00Z = 18:00 Asia/Shanghai — EndLocal of second window (exclusive).
        using var document = JsonDocument.Parse(
            """
            {
              "model": "cheap",
              "timestamp": "2026-07-15T10:00:00Z",
              "result": { "answer": "abcdefghijkl" },
              "stats": {
                "total_llm_time_s": 1.5,
                "total_tool_time_s": 0.25,
                "prompt_cache": { "cached_tokens": 100 }
              },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 1000 },
                { "type": "tool_call", "prompt_tokens_est": 9999 },
                { "type": "llm_call", "prompt_tokens_est": 1500 }
              ]
            }
            """);

        var cost = RelayCostEstimator.EstimateReport(document.RootElement);

        Assert.True(cost.Priced);
        Assert.Equal(0.00023912, cost.CostUsd, precision: 10);
    }

    // ── Schedule math: balanced (DeepSeek) model ─────────────────

    [Fact]
    public void BalancedModel_InsidePeakWindow_DoublesRates()
    {
        // 2026-07-15T06:00:00Z = 14:00 Asia/Shanghai — second peak window start (inclusive).
        // Same token counts as the existing balanced test: uncached=1500, cached=2000, output=200.
        // base cost = 0.00083375; peak = 2× = 0.0016675.
        using var document = JsonDocument.Parse(
            $$"""
            {
              "model": "balanced",
              "timestamp": "2026-07-15T06:00:00Z",
              "result": { "answer": "{{new string('x', 400)}}" },
              "stats": { "prompt_cache": { "cached_tokens": 2000 } },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 1000 },
                { "type": "llm_call", "prompt_tokens_est": 1500 },
                { "type": "tool_call", "prompt_tokens_est": 99999 }
              ]
            }
            """);

        var cost = RelayCostEstimator.EstimateReport(document.RootElement);

        Assert.True(cost.Priced);
        Assert.Equal(1_500, cost.PromptTokens);
        Assert.Equal(2_000, cost.CachedTokens);
        Assert.Equal(200, cost.OutputTokens);
        Assert.Equal(0.0016675, cost.CostUsd, precision: 10);
    }

    // ── Non-DeepSeek model unaffected by peak windows ────────────

    [Fact]
    public void ClaudeSonnet_InsideDeepSeekPeak_Unaffected()
    {
        // Claude Sonnet has no Windows — peak timestamp must not affect its rates.
        // uncached=1500, cached=100, output=ceil(12/4)+2*50=103.
        // rates: input 3.0, cached 0.30, output 15.0.
        // cost = (1500*3.0 + 100*0.30 + 103*15.0) / 1_000_000
        //      = (4500 + 30 + 1545) / 1_000_000 = 6075 / 1_000_000 = 0.006075.
        using var document = JsonDocument.Parse(
            """
            {
              "model": "claude-sonnet",
              "timestamp": "2026-07-15T01:00:00Z",
              "result": { "answer": "abcdefghijkl" },
              "stats": {
                "total_llm_time_s": 1.5,
                "total_tool_time_s": 0.25,
                "prompt_cache": { "cached_tokens": 100 }
              },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 1000 },
                { "type": "tool_call", "prompt_tokens_est": 9999 },
                { "type": "llm_call", "prompt_tokens_est": 1500 }
              ]
            }
            """);

        var cost = RelayCostEstimator.EstimateReport(document.RootElement);

        Assert.True(cost.Priced);
        Assert.Equal("claude-sonnet", cost.Model);
        Assert.Equal(0.006075, cost.CostUsd, precision: 10);
    }

    // ── Unknown model ────────────────────────────────────────────

    [Fact]
    public void UnknownModel_WithPeakTimestamp_StillReturnsPricedFalse()
    {
        using var document = JsonDocument.Parse(
            """
            {
              "model": "nonexistent-model-xyz",
              "timestamp": "2026-07-15T01:00:00Z",
              "result": { "answer": "hello" },
              "stats": { "prompt_cache": { "cached_tokens": 100 } },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 500 }
              ]
            }
            """);

        var cost = RelayCostEstimator.EstimateReport(document.RootElement);

        Assert.False(cost.Priced, "unknown model must return Priced=false even with a timestamp");
        Assert.Equal("nonexistent-model-xyz", cost.Model);
        Assert.Equal(0d, cost.CostUsd);
    }

    // ── Missing timestamp ────────────────────────────────────────

    [Fact]
    public void MissingTimestamp_DefaultsToBaseRates()
    {
        // No "timestamp" field → evaluationInstant falls back to DateTime.MinValue →
        // no window matches → multiplier 1×.
        using var document = JsonDocument.Parse(
            """
            {
              "model": "cheap",
              "result": { "answer": "abcdefghijkl" },
              "stats": {
                "total_llm_time_s": 1.5,
                "total_tool_time_s": 0.25,
                "prompt_cache": { "cached_tokens": 100 }
              },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 1000 },
                { "type": "tool_call", "prompt_tokens_est": 9999 },
                { "type": "llm_call", "prompt_tokens_est": 1500 }
              ]
            }
            """);

        var cost = RelayCostEstimator.EstimateReport(document.RootElement);

        Assert.True(cost.Priced);
        Assert.Equal(0.00023912, cost.CostUsd, precision: 10);
    }

    // ── Updated rate verification ────────────────────────────────

    [Fact]
    public void [ENCRYPTED:fastly]p2mN-vkrskvgifrrmz_KuOI8UvF25oR-()
    {
        // GLM 5.2: input 1.40, cached 0.26, output 4.40.
        // uncached=2000, cached=500, output=ceil(40/4)+50=60.
        // cost = (2000*1.40 + 500*0.26 + 60*4.40) / 1_000_000
        //      = (2800 + 130 + 264) / 1_000_000 = 3194 / 1_000_000 = 0.003194.
        using var document = JsonDocument.Parse(
            $$"""
            {
              "model": "glm-5.2",
              "result": { "answer": "{{new string('y', 40)}}" },
              "stats": { "prompt_cache": { "cached_tokens": 500 } },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 2000 }
              ]
            }
            """);

        var cost = RelayCostEstimator.EstimateReport(document.RootElement);

        Assert.True(cost.Priced);
        Assert.Equal("glm-5.2", cost.Model);
        Assert.Equal(0.003194, cost.CostUsd, precision: 10);
    }

    [Fact]
    public void ClaudeOpus_IncludesCacheWriteRate()
    {
        // Claude Opus: input 5.0, cached 0.50, cache-write 6.25, output 25.0.
        // uncached=1000, cached=200, cache-write=150, output=ceil(64/4)+3*50=166.
        // cost = (1000*5.0 + 200*0.50 + 150*6.25 + 166*25.0) / 1_000_000
        //      = (5000 + 100 + 937.5 + 4150) / 1_000_000 = 10187.5 / 1_000_000 = 0.0101875.
        using var document = JsonDocument.Parse(
            """
            {
              "model": "claude-opus-1m",
              "result": { "answer": "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!?" },
              "stats": {
                "prompt_cache": { "cached_tokens": 200, "cache_write_tokens": 150 }
              },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 500 },
                { "type": "llm_call", "prompt_tokens_est": 800 },
                { "type": "llm_call", "prompt_tokens_est": 1000 }
              ]
            }
            """);

        var cost = RelayCostEstimator.EstimateReport(document.RootElement);

        Assert.True(cost.Priced);
        Assert.Equal("claude-opus-1m", cost.Model);
        Assert.Equal(0.0101875, cost.CostUsd, precision: 10);
    }

    [Fact]
    public void KimiK2_UpdatedCachedInputRate()
    {
        // kimi-k2: input 0.95, cached 0.19, cache-write 0.95, output 4.0.
        // uncached=1000, cached=300, output=ceil(40/4)+50=60.
        // cost = (1000*0.95 + 300*0.19 + 60*4.0) / 1_000_000
        //      = (950 + 57 + 240) / 1_000_000 = 1247 / 1_000_000 = 0.001247.
        using var document = JsonDocument.Parse(
            $$"""
            {
              "model": "kimi-k2",
              "result": { "answer": "{{new string('y', 40)}}" },
              "stats": { "prompt_cache": { "cached_tokens": 300 } },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 1000 }
              ]
            }
            """);

        var cost = RelayCostEstimator.EstimateReport(document.RootElement);

        Assert.True(cost.Priced);
        Assert.Equal("kimi-k2", cost.Model);
        Assert.Equal(0.001247, cost.CostUsd, precision: 10);
    }

    [Fact]
    public void Gpt5_IncludesCachedInputRate()
    {
        // GPT-5: input 1.25, cached 0.125, output 10.0.
        // uncached=1000, cached=500, output=ceil(64/4)+2*50=116.
        // cost = (1000*1.25 + 500*0.125 + 116*10.0) / 1_000_000
        //      = (1250 + 62.5 + 1160) / 1_000_000 = 2472.5 / 1_000_000 = 0.0024725.
        using var document = JsonDocument.Parse(
            $$"""
            {
              "model": "gpt-5",
              "result": { "answer": "{{new string('x', 64)}}" },
              "stats": { "prompt_cache": { "cached_tokens": 500 } },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 500 },
                { "type": "llm_call", "prompt_tokens_est": 1000 }
              ]
            }
            """);

        var cost = RelayCostEstimator.EstimateReport(document.RootElement);

        Assert.True(cost.Priced);
        Assert.Equal("gpt-5", cost.Model);
        Assert.Equal(0.0024725, cost.CostUsd, precision: 10);
    }

    // ── Explicit evaluation instant (testability parameter) ──────

    [Fact]
    public void ExplicitEvaluationInstant_OverridesReportTimestamp()
    {
        // Report timestamp is in peak window, but explicit parameter is off-peak.
        using var document = JsonDocument.Parse(
            """
            {
              "model": "cheap",
              "timestamp": "2026-07-15T01:00:00Z",
              "result": { "answer": "abcdefghijkl" },
              "stats": {
                "total_llm_time_s": 1.5,
                "total_tool_time_s": 0.25,
                "prompt_cache": { "cached_tokens": 100 }
              },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 1000 },
                { "type": "tool_call", "prompt_tokens_est": 9999 },
                { "type": "llm_call", "prompt_tokens_est": 1500 }
              ]
            }
            """);

        // Explicit off-peak instant overrides the peak timestamp in the report.
        var offPeak = DateTime.Parse("2026-07-15T00:00:00Z", null, DateTimeStyles.AdjustToUniversal);
        var cost = RelayCostEstimator.EstimateReport(document.RootElement, offPeak);

        Assert.True(cost.Priced);
        Assert.Equal(0.00023912, cost.CostUsd, precision: 10);
    }

    [Fact]
    public void ExplicitEvaluationInstant_PeakOverridesOffPeakReport()
    {
        // Report timestamp is off-peak, but explicit parameter is in peak window.
        using var document = JsonDocument.Parse(
            """
            {
              "model": "cheap",
              "timestamp": "2026-07-15T00:00:00Z",
              "result": { "answer": "abcdefghijkl" },
              "stats": {
                "total_llm_time_s": 1.5,
                "total_tool_time_s": 0.25,
                "prompt_cache": { "cached_tokens": 100 }
              },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 1000 },
                { "type": "tool_call", "prompt_tokens_est": 9999 },
                { "type": "llm_call", "prompt_tokens_est": 1500 }
              ]
            }
            """);

        var peak = DateTime.Parse("2026-07-15T06:00:00Z", null, DateTimeStyles.AdjustToUniversal);
        var cost = RelayCostEstimator.EstimateReport(document.RootElement, peak);

        Assert.True(cost.Priced);
        Assert.Equal(0.00047824, cost.CostUsd, precision: 10);
    }

    // ── Cache-write tokens also multiplied by peak window ────────

    [Fact]
    public void CheapModel_PeakMultipliesCacheWriteTokens()
    {
        // uncached=3000, cached=1000, cache-write=500, output=ceil(64/4)+3*50=166.
        // cheap rates: input 0.14, cached 0.0028, cache-write 0.14, output 0.28.
        // base = (3000*0.14 + 1000*0.0028 + 500*0.14 + 166*0.28) / 1_000_000
        //      = (420 + 2.8 + 70 + 46.48) / 1_000_000 = 539.28 / 1_000_000 = 0.00053928.
        // peak = 2× = 0.00107856.
        using var document = JsonDocument.Parse(
            """
            {
              "model": "cheap",
              "timestamp": "2026-07-15T01:00:00Z",
              "result": { "answer": "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!?" },
              "stats": {
                "prompt_cache": { "cached_tokens": 1000, "cache_write_tokens": 500 }
              },
              "timeline": [
                { "type": "llm_call", "prompt_tokens_est": 1000 },
                { "type": "llm_call", "prompt_tokens_est": 2000 },
                { "type": "llm_call", "prompt_tokens_est": 3000 }
              ]
            }
            """);

        var cost = RelayCostEstimator.EstimateReport(document.RootElement);

        Assert.True(cost.Priced);
        Assert.Equal(500, cost.CacheWriteTokens);
        Assert.Equal(0.00107856, cost.CostUsd, precision: 10);
    }
}

namespace VisualRelay.Core.Costs;

// Rates are USD per 1,000,000 tokens, matching Relay's pricing.json unit.
// CacheWrite: when null, cache-write tokens are billed at the Input rate (the
// industry-standard fallback — the provider charges for writing to the cache).
// CachedInput: when null, cached tokens are billed at the Input rate (no discount).
internal sealed record ModelPricing(
    double Input,
    double Output,
    double? CachedInput = null,
    double? CacheWrite = null,
    IReadOnlyList<RateWindow>? Windows = null);

internal static class RelayPricing
{
    // DeepSeek time-of-day peak pricing (provisional, 2026-07-07):
    // 2× during 09:00–12:00 and 14:00–18:00 Asia/Shanghai (UTC+8, no DST).
    // Announced 2026-06-30 (TechNode), effective mid-July 2026 with V4 release.
    // Official docs had not published the schedule as of 2026-07-07 — update when
    // api-docs.deepseek.com/quick_start/pricing publishes the authoritative window.
    private static readonly RateWindow[] DeepseekPeakWindows =
    [
        new(new(9, 0), new(12, 0), "Asia/Shanghai", 2.0),
        new(new(14, 0), new(18, 0), "Asia/Shanghai", 2.0),
    ];

    public static IReadOnlyDictionary<string, ModelPricing> Default { get; } =
        new Dictionary<string, ModelPricing>(StringComparer.Ordinal)
        {
            // deepseek-v4-flash (api-docs.deepseek.com, 2026-07-07); peak window 2× above
            ["cheap"] = new(0.14, 0.28, 0.0028, 0.14) { Windows = DeepseekPeakWindows },
            // deepseek-v4-pro (api-docs.deepseek.com, 2026-07-07); peak window 2× above
            ["balanced"] = new(0.435, 0.87, 0.003625, 0.435) { Windows = DeepseekPeakWindows },
            // GLM 5.2 via HF / Z.AI (docs.z.ai/guides/overview/pricing, 2026-07-07); CacheWrite→Input fallback (1.40)
            ["frontier"] = new(1.40, 4.40, 0.26),
            // GLM 5.2 via HF (zai-org), 2026-07-07; same as frontier
            ["glm-5.2"] = new(1.40, 4.40, 0.26),
            // Qwen3-VL-235B-A22B-Instruct (openrouter.ai, 2026-07-07)
            ["vision"] = new(0.20, 0.88),
            // Opus (docs.anthropic.com, 2026-07-07); cache hit 0.1×, write 1.25× (5-min TTL)
            ["claude-opus-1m"] = new(5.0, 25.0, 0.50, 6.25),
            // Sonnet (docs.anthropic.com, 2026-07-07); sticker $3/$15; Sonnet 5 intro $2/$10 through 2026-08-31
            ["claude-sonnet"] = new(3.0, 15.0, 0.30, 3.75),
            // Haiku 4.5 (docs.anthropic.com, 2026-07-07); cache hit 0.1×, write 1.25×
            ["claude-haiku"] = new(1.0, 5.0, 0.10, 1.25),
            // GPT-5 (openrouter.ai, 2026-07-07); cached input 0.1×
            ["gpt-5"] = new(1.25, 10.0, 0.125),
